create or replace function public._seed_sources(ks text)
returns jsonb language sql immutable set search_path = public as $f$
  select coalesce(jsonb_agg(
    case k
      when 'G' then '{"field":"awards","title":"Gallantry award recipients","publisher":"Gallantry Awards Portal, Ministry of Defence","url":"https://gallantryawards.gov.in/","tier":"primary","accessed":"2026-10-22"}'::jsonb
      when 'N' then '{"field":"memorials","title":"Param Yodha Sthal and Circles of Honour","publisher":"National War Memorial, Ministry of Defence","url":"https://nationalwarmemorial.gov.in/","tier":"primary","accessed":"2026-10-22"}'::jsonb
      when 'A' then '{"field":"unit","title":"Regimental honours","publisher":"Indian Army","url":"https://indianarmy.nic.in/","tier":"primary","accessed":"2026-10-22"}'::jsonb
      when 'I' then '{"field":"unit","title":"Gallantry honours","publisher":"Indian Air Force","url":"https://indianairforce.nic.in/","tier":"primary","accessed":"2026-10-22"}'::jsonb
      when 'V' then '{"field":"unit","title":"Naval history","publisher":"Indian Navy","url":"https://indiannavy.nic.in/","tier":"primary","accessed":"2026-10-22"}'::jsonb
      when 'P' then '{"field":"summary","title":"Press releases and commemorations","publisher":"Press Information Bureau, Government of India","url":"https://pib.gov.in/","tier":"primary","accessed":"2026-10-22"}'::jsonb
      when 'M' then '{"field":"summary","title":"History Division publications","publisher":"Ministry of Defence, Government of India","url":"https://mod.gov.in/","tier":"primary","accessed":"2026-10-22"}'::jsonb
      when 'U' then '{"field":"summary","title":"ONUC — United Nations Operation in the Congo","publisher":"United Nations Peacekeeping","url":"https://peacekeeping.un.org/en/mission/past/onuc.htm","tier":"primary","accessed":"2026-10-22"}'::jsonb
    end order by o), '[]'::jsonb)
  from regexp_split_to_table(ks, '') with ordinality t(k, o)
$f$;

create or replace function public._seed_media(m jsonb, p_martyr uuid, p_memorial uuid, p_war uuid)
returns uuid language plpgsql set search_path = public as $f$
declare u text; mid uuid;
begin
  u := replace(replace(m->>1, '~T', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/'), '~U', 'https://upload.wikimedia.org/wikipedia/commons/');
  select id into mid from public.media where url = u limit 1;
  if mid is null then
    insert into public.media (kind,title,url,width,height,credit,license,license_detail,source_url,martyr_id,memorial_id,war_id,verification)
    values ('photo', m->>0, u, (m->>2)::int, (m->>3)::int, m->>4, (m->>5)::public.media_license, m->>6,
      replace(m->>7, '~C', 'https://commons.wikimedia.org/wiki/'), p_martyr, p_memorial, p_war, 'verified')
    returning id into mid;
  end if;
  return mid;
end $f$;

create or replace function public._seed_people(d jsonb)
returns void language plpgsql set search_path = public as $f$
declare r jsonb; rid uuid;
begin
  for r in select * from jsonb_array_elements(d) loop
    insert into public.martyrs (slug,full_name,rank,service_number,service_branch,regiment,unit,date_of_birth,status,date_of_action,birth_village,birth_district,birth_state,war_id,operation,place_of_action,biography,sources,verification)
    values (r->>0, r->>1, r->>2, r->>3, r->>4, r->>5, r->>6, (r->>7)::date, (r->>8)::public.record_status, (r->>9)::date, r->>10, r->>11, r->>12,
      (select id from public.wars where slug = r->>13), r->>14, r->>15, r->>16, public._seed_sources(r->>17), 'verified')
    returning id into rid;
    insert into public.awards (martyr_id,name,year,posthumous,citation,citation_verbatim,gazette_ref)
    values (rid, r->>18, (r->>19)::int, (r->>20)::boolean, r->>21, false, r->>22);
    insert into public.martyr_memorials (martyr_id, memorial_id)
      select rid, m.id from jsonb_array_elements_text(r->23) s join public.memorials m on m.slug = s;
    if jsonb_typeof(r->24) = 'array' then
      update public.martyrs set portrait_media_id = public._seed_media(r->24, rid, null, null) where id = rid;
    end if;
  end loop;
end $f$;

do $do$
declare
  d jsonb := $j${"w":[["first-kashmir-war-1947","First India–Pakistan War (Jammu & Kashmir)","war","1947-10-22","1949-01-01","1947 – 1949","Jammu & Kashmir","The first war of independent India, fought to defend Jammu & Kashmir after Pakistan-backed tribal raiders crossed into the state in October 1947.","Weeks after Independence, armed tribal lashkars supported by Pakistan invaded the princely state of Jammu & Kashmir. After Maharaja Hari Singh signed the Instrument of Accession on 26 October 1947, Indian troops were airlifted to Srinagar the next morning and held the Valley. Fighting spread across Naushera, Jhangar, Rajouri, Poonch, Tithwal, Zoji La and Leh over the following fourteen months. A United Nations-brokered ceasefire took effect on 1 January 1949. Five of the first Param Vir Chakras were awarded for actions in this war.",[["1947-10-22","22 Oct 1947","Raiders cross into J&K","Tribal lashkars backed by Pakistan advance on Muzaffarabad and Baramulla."],["1947-10-26","26 Oct 1947","Instrument of Accession","Maharaja Hari Singh accedes the state to India."],["1947-10-27","27 Oct 1947","Airlift to Srinagar","1 Sikh lands at Srinagar airfield — now marked as Infantry Day."],["1947-11-03","3 Nov 1947","Battle of Badgam","A company of 4 Kumaon under Maj Somnath Sharma holds off a far larger force near the airfield."],["1948-02-06","6 Feb 1948","Defence of Taindhar","Naik Jadunath Singh's picquet beats back repeated assaults in the Naushera sector."],["1948-11-01","1 Nov 1948","Operation Bison","Stuart tanks are taken over Zoji La, at the time the highest altitude tanks had operated."],["1949-01-01","1 Jan 1949","Ceasefire","A UN-brokered ceasefire comes into force along the line held by the two armies."]],"MA",["Jadunath Memorial at Taindhar Top near Naushera J&K","~T2/28/Jadunath_Memorial_at_Taindhar_Top_near_Naushera_J%26K.jpg/1920px-Jadunath_Memorial_at_Taindhar_Top_near_Naushera_J%26K.jpg",1600,2133,"Ashik2k9","CC-BY-SA","CC BY-SA 3.0","~CFile:Jadunath_Memorial_at_Taindhar_Top_near_Naushera_J%26K.jpg"]],["onuc-congo-1961","UN Operation in the Congo (ONUC)","peacekeeping","1960-07-14","1964-06-30","1960 – 1964","Katanga, Republic of the Congo","India's largest early UN peacekeeping commitment, during which Capt G.S. Salaria became the only UN peacekeeper to receive the Param Vir Chakra.","The United Nations Operation in the Congo was established in July 1960 to help the newly independent Republic of the Congo restore order and, later, to end the secession of Katanga province. India contributed an infantry brigade group, 99 Infantry Brigade, along with air force and support elements. Indian troops fought in several actions around Elisabethville in 1961 and 1962. The mission ended in June 1964.",[["1960-07-14","14 Jul 1960","ONUC established","Security Council Resolution 143 authorises the operation."],["1961-03","Mar 1961","Indian brigade deploys","99 Infantry Brigade arrives in the Congo."],["1961-12-05","5 Dec 1961","Action at Elisabethville","Capt Salaria leads a charge against a roadblock held by mercenaries and Katangese gendarmes."],["1964-06-30","30 Jun 1964","Mission ends","ONUC withdraws from the Congo."]],"UA",null],["sino-indian-war-1962","Sino-Indian War","war","1962-10-20","1962-11-21","1962","Ladakh and NEFA (Arunachal Pradesh)","A month-long border war with China fought at extreme altitude in Ladakh and the North-East Frontier Agency.","On 20 October 1962 the People's Liberation Army launched simultaneous offensives in Ladakh and in the Kameng sector of NEFA. Indian troops, often outnumbered, under-equipped and without winter clothing, fought a series of stubborn defensive actions — at Namka Chu, Bum La, Sela–Nuranang, Walong, Chushul and Rezang La. China declared a unilateral ceasefire on 21 November 1962. The defence of Rezang La by C Company, 13 Kumaon, remains one of the most celebrated last stands in Indian military history.",[["1962-10-20","20 Oct 1962","Offensive begins","Attacks open at Namka Chu in NEFA and on posts north of Pangong Tso in Ladakh."],["1962-10-23","23 Oct 1962","IB Ridge, Bum La","Subedar Joginder Singh's platoon of 1 Sikh fights until its ammunition is spent."],["1962-11-17","17 Nov 1962","Nuranang","Rifleman Jaswant Singh Rawat of 4 Garhwal Rifles helps silence an enemy machine gun."],["1962-11-18","18 Nov 1962","Rezang La","C Company, 13 Kumaon, under Maj Shaitan Singh fights almost to the last man."],["1962-11-21","21 Nov 1962","Ceasefire","China announces a unilateral ceasefire and withdrawal."]],"MA",["Rezang La war memorial site","~Td/d1/Rezang_La_war_memorial_site.jpg/1920px-Rezang_La_war_memorial_site.jpg",1600,1200,"Runabhattacharjee","CC0","CC0","~CFile:Rezang_La_war_memorial_site.jpg"]],["indo-pak-war-1965","India–Pakistan War of 1965","war","1965-08-05","1965-09-23","1965","Jammu & Kashmir, Punjab, Rajasthan","Sparked by Operation Gibraltar, the war saw some of the largest tank battles since the Second World War, at Asal Uttar and Chawinda.","In August 1965 Pakistan infiltrated armed men into Jammu & Kashmir under Operation Gibraltar, followed on 1 September by an armoured thrust towards Akhnoor (Operation Grand Slam). India responded by opening a front across the international border in Punjab on 6 September. The Battle of Asal Uttar near Khem Karan halted Pakistan's armoured offensive, while Indian armour fought at Phillora and Chawinda in the Sialkot sector. A UN-mandated ceasefire took effect on 23 September 1965, followed by the Tashkent Declaration in January 1966.",[["1965-08-05","5 Aug 1965","Operation Gibraltar","Armed infiltrators cross the ceasefire line into Jammu & Kashmir."],["1965-09-01","1 Sep 1965","Operation Grand Slam","Pakistani armour attacks in the Chhamb–Akhnoor sector."],["1965-09-06","6 Sep 1965","Punjab front opens","Indian forces advance towards Lahore and Sialkot."],["1965-09-10","8–10 Sep 1965","Battle of Asal Uttar","Pakistan's armoured thrust is broken near Khem Karan; CQMH Abdul Hamid destroys several tanks."],["1965-09-11","11–16 Sep 1965","Phillora and Chawinda","17 Poona Horse under Lt Col A.B. Tarapore fights a series of tank battles."],["1965-09-23","23 Sep 1965","Ceasefire","Hostilities end under a UN Security Council resolution."]],"MA",["Martyr statue, Battle of Asal Uttar, Punjab","~T6/63/Martyr_statue%2C_Battle_of_Asal_Uttar%2C_Punjab.jpg/1920px-Martyr_statue%2C_Battle_of_Asal_Uttar%2C_Punjab.jpg",1600,1200,"Bhaskea","CC-BY-SA","CC BY-SA 4.0","~CFile:Martyr_statue,_Battle_of_Asal_Uttar,_Punjab.jpg"]],["indo-pak-war-1971","India–Pakistan War of 1971","war","1971-12-03","1971-12-16","1971","Eastern and Western fronts, Arabian Sea, Bay of Bengal","A thirteen-day war on two fronts that ended with the surrender of 93,000 troops in Dhaka and the birth of Bangladesh.","After months of crisis in East Pakistan and the flight of millions of refugees into India, Pakistan launched pre-emptive air strikes on Indian airfields on 3 December 1971. India's Army, Navy and Air Force responded on both fronts: a rapid campaign in the east converged on Dhaka, while in the west actions such as Longewala, Basantar and the naval strikes on Karachi held and pushed back Pakistani forces. On 16 December 1971 Lt Gen A.A.K. Niazi signed the Instrument of Surrender before Lt Gen Jagjit Singh Aurora. The day is marked in India as Vijay Diwas.",[["1971-12-03","3 Dec 1971","War begins","Pakistan's air strikes on Indian airfields open the war."],["1971-12-04","4–5 Dec 1971","Longewala and Karachi","A company of 23 Punjab holds Longewala; the Navy's Operation Trident strikes Karachi harbour."],["1971-12-09","9 Dec 1971","INS Khukri","The frigate is torpedoed off Diu; Capt M.N. Mulla goes down with his ship."],["1971-12-14","14 Dec 1971","Air battle over Srinagar","Fg Offr N.J.S. Sekhon takes on attacking Sabres alone."],["1971-12-16","16 Dec 1971","Basantar and surrender","Battle of Basantar in the west; the Instrument of Surrender is signed in Dhaka."]],"MAV",["1971 Instrument of Surrender","~U1/16/1971_Instrument_of_Surrender.jpg",1600,1138,"Indian Navy","GODL-India","GODL-India","~CFile:1971_Instrument_of_Surrender.jpg"]],["siachen-operation-meghdoot","Siachen Glacier — Operation Meghdoot","operation","1984-04-13",null,"1984 – present","Siachen Glacier and Saltoro Ridge, Ladakh","India's occupation and defence of the Saltoro Ridge above the Siachen Glacier — the highest battlefield in the world.","On 13 April 1984 the Indian Army and Air Force launched Operation Meghdoot to secure the passes of the Saltoro Ridge before Pakistani forces could occupy them. Posts on the glacier sit at altitudes above 6,000 metres, where weather and terrain have claimed more lives than combat. In June 1987, under Operation Rajiv, a small team led by Naib Subedar Bana Singh captured the dominating Quaid Post, later renamed Bana Post in his honour.",[["1984-04-13","13 Apr 1984","Operation Meghdoot","Troops are airlifted to secure Sia La and Bilafond La."],["1987-06-26","26 Jun 1987","Operation Rajiv","Naib Subedar Bana Singh's team captures Quaid Post at about 6,500 m."],["2003-11-26","Nov 2003","Ceasefire","A ceasefire along the Line of Control extends to the Siachen sector."]],"AM",["Leh - Hall of Fame Museum (13)","~Ta/a7/Leh_-_Hall_of_Fame_Museum_%2813%29.jpg/1920px-Leh_-_Hall_of_Fame_Museum_%2813%29.jpg",1600,1200,"Deepa 07","CC-BY-SA","CC BY-SA 4.0","~CFile:Leh_-_Hall_of_Fame_Museum_(13).jpg"]],["ipkf-operation-pawan","Indian Peace Keeping Force — Operation Pawan","peacekeeping","1987-07-29","1990-03-24","1987 – 1990","Northern and Eastern Sri Lanka","India's deployment to Sri Lanka under the Indo-Sri Lanka Accord, which turned into a prolonged counter-insurgency campaign against the LTTE.","Following the Indo-Sri Lanka Accord of July 1987, the Indian Peace Keeping Force was sent to the north and east of Sri Lanka. When the LTTE refused to disarm, the IPKF launched Operation Pawan in October 1987 to secure the Jaffna peninsula. The deployment lasted until March 1990, and more than a thousand Indian soldiers lost their lives.",[["1987-07-29","29 Jul 1987","Indo-Sri Lanka Accord","The accord is signed in Colombo; IPKF begins to deploy."],["1987-10-10","10 Oct 1987","Operation Pawan","IPKF operations begin to take control of Jaffna."],["1987-11-25","25 Nov 1987","Kantharodai","Maj R. Parameswaran of 8 Mahar falls leading a counter-ambush."],["1990-03-24","24 Mar 1990","Withdrawal","The last IPKF troops leave Sri Lanka."]],"AM",null],["kargil-war-1999","Kargil War (Operation Vijay)","war","1999-05-03","1999-07-26","1999","Kargil district, Ladakh","High-altitude war to evict Pakistani troops and militants who had occupied heights along the Line of Control in the Kargil sector.","In May 1999 shepherds and patrols discovered that Pakistani soldiers and militants had occupied positions on the ridgelines above the Srinagar–Leh highway in the Dras, Kaksar, Batalik and Turtuk sectors. Under Operation Vijay the Indian Army fought its way up near-vertical slopes at altitudes up to 5,500 metres, supported by the Indian Air Force's Operation Safed Sagar. Tololing, Point 5140, Tiger Hill and Point 4875 were recaptured in a series of night assaults. The operation was declared a success on 26 July 1999, now observed as Kargil Vijay Diwas. Four Param Vir Chakras were awarded.",[["1999-05-03","3 May 1999","Intrusions detected","Shepherds report armed intruders on the heights near Batalik."],["1999-05-26","26 May 1999","Operation Safed Sagar","The Indian Air Force begins air strikes."],["1999-06-13","13 Jun 1999","Tololing","2 Rajputana Rifles captures Tololing after weeks of fighting."],["1999-06-20","20 Jun 1999","Point 5140","13 JAK Rifles under Capt Vikram Batra captures Point 5140."],["1999-07-04","4 Jul 1999","Tiger Hill","18 Grenadiers and 8 Sikh recapture Tiger Hill."],["1999-07-07","7 Jul 1999","Point 4875","Capt Batra falls in the final assault; the feature is renamed Batra Top."],["1999-07-26","26 Jul 1999","Kargil Vijay Diwas","Operation Vijay is declared successfully concluded."]],"MAP",["The Tiger Hill (3976856895)","~T0/0d/The_Tiger_Hill_%283976856895%29.jpg/1920px-The_Tiger_Hill_%283976856895%29.jpg",1600,1200,"taNvir kohli","CC-BY","CC BY 2.0","~CFile:The_Tiger_Hill_(3976856895).jpg"]],["mumbai-2008-operation-black-tornado","26/11 Mumbai — Operation Black Tornado","counter-insurgency","2008-11-26","2008-11-29","2008","Mumbai, Maharashtra","The National Security Guard operation to clear the Taj Mahal Palace hotel, the Oberoi–Trident and Nariman House after the 26 November 2008 terrorist attacks.","On the night of 26 November 2008, ten terrorists who had arrived by sea attacked several sites across south Mumbai. Commandos of the National Security Guard were flown in and launched Operation Black Tornado, clearing the hotels and Nariman House floor by floor over three days. Major Sandeep Unnikrishnan of 51 Special Action Group was killed leading his team inside the Taj Mahal Palace hotel.",[["2008-11-26","26 Nov 2008","Attacks begin","Coordinated attacks at CST station, Leopold Cafe, the Taj, the Oberoi–Trident and Nariman House."],["2008-11-27","27 Nov 2008","NSG arrives","Operation Black Tornado begins."],["2008-11-28","28 Nov 2008","Inside the Taj","Maj Sandeep Unnikrishnan falls while rescuing hostages and engaging the attackers."],["2008-11-29","29 Nov 2008","Operation concludes","The Taj Mahal Palace hotel is declared clear."]],"PM",null],["jammu-kashmir-counter-insurgency","Counter-insurgency operations, Jammu & Kashmir","counter-insurgency",null,null,"1989 – present","Jammu & Kashmir","Decades of operations against armed infiltration and militancy along the Line of Control and in the hinterland of Jammu & Kashmir.","Since the late 1980s the Army, the Rashtriya Rifles, central armed police forces and the J&K Police have conducted continuous operations against infiltration across the Line of Control and against militant groups. Many of India's peacetime gallantry awards — the Ashoka, Kirti and Shaurya Chakras — have been earned in these operations.",[["1990","1990","Rashtriya Rifles raised","A dedicated counter-insurgency force is raised from the Army."],["2009-03-21","21 Mar 2009","Haphruda forest","Maj Mohit Sharma of 1 Para (SF) falls in close-quarter combat in Kupwara."],["2016-05-27","27 May 2016","Shamshabari range","Hav Hangpan Dada of 35 Rashtriya Rifles falls intercepting infiltrators near Naugam."]],"AM",null],["galwan-valley-2020","Galwan Valley Clash, Eastern Ladakh","operation","2020-06-15","2020-06-15","2020","Galwan Valley, Ladakh","A violent clash with Chinese troops on the Line of Actual Control during the 2020 standoff in eastern Ladakh, in which twenty Indian soldiers were killed.","During the standoff along the Line of Actual Control that began in May 2020, a clash broke out in the Galwan Valley on the night of 15 June 2020. Troops of 16 Bihar led by their Commanding Officer, Colonel B. Santosh Babu, and other units fought without firearms in darkness and extreme terrain. Twenty Indian soldiers lost their lives. Col Santosh Babu was posthumously awarded the Maha Vir Chakra in January 2021.",[["2020-05-05","5 May 2020","Standoff begins","Face-offs at Pangong Tso begin the eastern Ladakh standoff."],["2020-06-15","15 Jun 2020","Galwan clash","Col B. Santosh Babu and nineteen soldiers are killed."],["2021-01-26","26 Jan 2021","Gallantry awards","Col Santosh Babu is awarded the Maha Vir Chakra posthumously."]],"PA",null]],"m":[["national-war-memorial","National War Memorial","New Delhi","New Delhi","Delhi",28.6127,77.2334,2019,"Ministry of Defence","Built in the C-Hexagon beside India Gate and dedicated to the nation on 25 February 2019, the memorial honours the armed forces personnel who have laid down their lives since Independence. Its four concentric circles — Amar Chakra, Veerta Chakra, Tyag Chakra and Rakshak Chakra — carry the names of more than 26,000 soldiers on granite tablets around a central obelisk and eternal flame.","Param Yodha Sthal, within the memorial, holds bronze busts of all twenty-one recipients of the Param Vir Chakra. The eternal flame of Amar Jawan Jyoti was merged with the flame here in January 2022.",[["National War Memorial","~T5/59/National_War_Memorial%2C_New_Delhi%2C_India.jpg/1920px-National_War_Memorial%2C_New_Delhi%2C_India.jpg",1600,917,"Sanket Oswal","CC-BY-SA","CC BY-SA 4.0","~CFile:National_War_Memorial,_New_Delhi,_India.jpg"],["National War Memorial in New Delhi 01","~Ta/ac/National_War_Memorial_in_New_Delhi_01.jpg/1920px-National_War_Memorial_in_New_Delhi_01.jpg",1600,2133,"Pinakpani","CC-BY-SA","CC BY-SA 4.0","~CFile:National_War_Memorial_in_New_Delhi_01.jpg"],["National War Memorial in India gate premises in New Delhi 04","~Tf/fe/National_War_Memorial_in_India_gate_premises_in_New_Delhi_04.jpg/1920px-National_War_Memorial_in_India_gate_premises_in_New_Delhi_04.jpg",1600,900,"Pinakpani","CC-BY-SA","CC BY-SA 4.0","~CFile:National_War_Memorial_in_India_gate_premises_in_New_Delhi_04.jpg"]]],["india-gate","India Gate (All India War Memorial)","New Delhi","New Delhi","Delhi",28.6129,77.2295,1931,"Government of India","Designed by Sir Edwin Lutyens and inaugurated in 1931, the 42-metre arch commemorates soldiers of the British Indian Army who died in the First World War and the Third Anglo-Afghan War. More than 13,000 names are inscribed on its surfaces.","For five decades the Amar Jawan Jyoti, lit beneath the arch in 1972 after the 1971 war, was the nation's tribute to its unknown soldiers.",[["India Gate (All India War Memorial)","~T0/06/India_Gate%2C_New_Delhi.jpg/1920px-India_Gate%2C_New_Delhi.jpg",1600,827,"Yann","CC-BY-SA","CC BY-SA 3.0","~CFile:India_Gate,_New_Delhi.jpg"]]],["kargil-war-memorial-dras","Kargil War Memorial","Dras","Kargil","Ladakh",34.4283,75.7608,2000,"Indian Army","Built by the Indian Army at Dras in the shadow of Tololing, the memorial commemorates the soldiers who fell during Operation Vijay in 1999. A sandstone wall carries the names of the fallen, and Tiger Hill and Tololing are visible from the grounds.","The memorial is the centre of Kargil Vijay Diwas observances every 26 July.",[["Kargil War Memorial","~T6/60/Kargilwarmemorialdarss5.jpg/1920px-Kargilwarmemorialdarss5.jpg",1600,1067,"Reflectionsbyprajakta","CC-BY-SA","CC BY-SA 4.0","~CFile:Kargilwarmemorialdarss5.jpg"],["WarMemorial Drass Ladakh India","~T0/07/WarMemorial_Drass_Ladakh_India.jpg/1920px-WarMemorial_Drass_Ladakh_India.jpg",1600,1200,"शंतनू","CC-BY-SA","CC BY-SA 2.5","~CFile:WarMemorial_Drass_Ladakh_India.jpg"],["Kargil war memorial","~T3/35/Kargil_war_memorial.jpg/1920px-Kargil_war_memorial.jpg",1600,900,"Liginjo","CC-BY-SA","CC BY-SA 4.0","~CFile:Kargil_war_memorial.jpg"]]],["rezang-la-war-memorial","Rezang La War Memorial","Chushul","Leh","Ladakh",33.5935,78.6584,1963,"Indian Army","Raised near Chushul to the men of C Company, 13th Battalion, the Kumaon Regiment, who defended Rezang La on 18 November 1962. The memorial was renovated and rededicated in November 2021.","Its inscription adapts Macaulay: 'How can a man die better than facing fearful odds, for the ashes of his fathers and the temples of his gods.'",[["Rezang La War Memorial","~Td/d1/Rezang_La_war_memorial_site.jpg/1920px-Rezang_La_war_memorial_site.jpg",1600,1200,"Runabhattacharjee","CC0","CC0","~CFile:Rezang_La_war_memorial_site.jpg"],["Rezang La War Memorial Plaque","~Ua/a9/Rezang_La_War_Memorial_Plaque.jpg",1600,1200,"Runabhattacharjee","CC0","CC0","~CFile:Rezang_La_War_Memorial_Plaque.jpg"],["Chushul war memorial of Rezang La battle in 1962","~U8/80/Chushul_war_memorial_of_Rezang_La_battle_in_1962.jpg",1600,1063,"Narender9","CC-BY-SA","CC BY-SA 3.0","~CFile:Chushul_war_memorial_of_Rezang_La_battle_in_1962.jpg"]]],["tawang-war-memorial","Tawang War Memorial","Tawang","Tawang","Arunachal Pradesh",27.5859,91.8594,1999,"Indian Army","A 40-foot stupa-style memorial overlooking Tawang, dedicated to the soldiers who died defending the Kameng sector during the 1962 war. The names of the fallen are inscribed on black granite tablets around it.","It carries the names of 2,420 soldiers who fell in the Kameng sector in 1962.",[["Tawang War Memorial","~Td/d4/Tawang_War_Memorial.jpg/1920px-Tawang_War_Memorial.jpg",1600,1052,"Rohit Sharma","CC-BY-SA","CC BY-SA 4.0","~CFile:Tawang_War_Memorial.jpg"],["Tawang War Memorial (Immortals)","~T3/3a/Tawang_War_Memorial_%28Immortals%29.jpg/1920px-Tawang_War_Memorial_%28Immortals%29.jpg",1600,925,"Rohit Sharma","CC-BY-SA","CC BY-SA 4.0","~CFile:Tawang_War_Memorial_(Immortals).jpg"]]],["jaswant-garh-war-memorial","Jaswant Garh War Memorial","Nuranang","Tawang","Arunachal Pradesh",27.5262,92.0335,null,"Indian Army","Built at Nuranang, near Sela Pass, at the site where Rifleman Jaswant Singh Rawat of 4 Garhwal Rifles fought on 17 November 1962.","Soldiers stationed here maintain his quarters as though he were still serving — one of the Army's most enduring traditions of remembrance.",[["Jaswant Garh War Memorial","~T6/61/Jaswant_Garh_War_Memorial%2C_tawang.jpg/1920px-Jaswant_Garh_War_Memorial%2C_tawang.jpg",1600,1067,"Rohit Sharma","CC-BY-SA","CC BY-SA 4.0","~CFile:Jaswant_Garh_War_Memorial,_tawang.jpg"]]],["longewala-war-memorial","Longewala War Memorial","Longewala","Jaisalmer","Rajasthan",27.5222,70.1574,null,"Indian Army (BSF assists)","Marks the battlefield where a company of 23 Punjab under Maj Kuldip Singh Chandpuri, supported by Indian Air Force Hunters at first light, halted a Pakistani armoured column on the night of 4–5 December 1971.","Captured tanks and vehicles from the battle are displayed at the site.",[["Longewala War Memorial","~T7/75/Longewala_War_Memorial.jpg/1920px-Longewala_War_Memorial.jpg",1600,1200,"Lakshmikanta Manna","CC0","CC0","~CFile:Longewala_War_Memorial.jpg"]]],["hall-of-fame-leh","Hall of Fame","Leh","Leh","Ladakh",34.1369,77.559,null,"Indian Army","A memorial and museum built by the Indian Army on the Leh–Kargil road, honouring soldiers who have served and fallen in Ladakh. Its galleries cover the wars of 1947–48, 1962, 1971 and 1999, and life on the Siachen Glacier.","One of the few places where visitors can see the equipment and conditions of high-altitude soldiering up close.",[["Hall of Fame","~T7/74/Hall_of_Fame_Entrance_%2848979441198%29.jpg/1920px-Hall_of_Fame_Entrance_%2848979441198%29.jpg",1600,1068,"Chris Hunkeler from Carlsbad, California, USA","CC-BY-SA","CC BY-SA 2.0","~CFile:Hall_of_Fame_Entrance_(48979441198).jpg"],["Leh - Hall of Fame Museum (13)","~Ta/a7/Leh_-_Hall_of_Fame_Museum_%2813%29.jpg/1920px-Leh_-_Hall_of_Fame_Museum_%2813%29.jpg",1600,1200,"Deepa 07","CC-BY-SA","CC BY-SA 4.0","~CFile:Leh_-_Hall_of_Fame_Museum_(13).jpg"]]],["victory-at-sea-visakhapatnam","Victory at Sea Memorial","Visakhapatnam","Visakhapatnam","Andhra Pradesh",17.7175,83.33,1996,"Indian Navy (Eastern Naval Command)","Built on Beach Road, Visakhapatnam, to commemorate the Indian Navy's role and the sailors who died in the 1971 war.","Wreaths are laid here every Navy Day (4 December) and Vijay Diwas (16 December).",[["Victory at Sea Memorial","~Ub/bf/Victory_at_Sea%2C_1971_Memorial%2C_Visakhapatnam.jpg",1600,2729,"Nivas10798","CC-BY-SA","CC BY-SA 4.0","~CFile:Victory_at_Sea,_1971_Memorial,_Visakhapatnam.jpg"]]],["ins-khukri-memorial-diu","INS Khukri Memorial","Diu","Diu","Dadra & Nagar Haveli and Daman & Diu",20.7086,70.9255,1999,"Indian Navy","On a hill overlooking the Arabian Sea at Diu, the memorial honours the 18 officers and 176 sailors of INS Khukri, sunk by a Pakistani submarine on 9 December 1971, and her commanding officer, Capt Mahendra Nath Mulla.","A scale model of the frigate stands in a glass enclosure at the centre of the memorial.",[["INS Khukri Memorial","~T9/9a/Model_of_INS_Khukri_at_memorial_of_the_ship%2C_2012.jpg/1920px-Model_of_INS_Khukri_at_memorial_of_the_ship%2C_2012.jpg",1600,1200,"Archan dave","CC-BY-SA","CC BY-SA 3.0","~CFile:Model_of_INS_Khukri_at_memorial_of_the_ship,_2012.jpg"],["Engraved stone about INS Khukri at the ship's memorial","~T4/46/Engraved_stone_about_INS_Khukri_at_the_ship%27s_memorial.jpg/1920px-Engraved_stone_about_INS_Khukri_at_the_ship%27s_memorial.jpg",1600,679,"Archan dave","CC-BY-SA","CC BY-SA 3.0","~CFile:Engraved_stone_about_INS_Khukri_at_the_ship%27s_memorial.jpg"]]],["asal-uttar-war-memorial","Asal Uttar War Memorial","Asal Uttar","Tarn Taran","Punjab",31.148,74.53,null,"Indian Army","Stands near Khem Karan on the site of the 1965 tank battle in which Pakistan's armoured offensive was defeated. It includes the memorial of CQMH Abdul Hamid, PVC.","Pakistani Patton tanks destroyed in the battle gave the area the name 'Patton Nagar'.",[["Asal Uttar War Memorial","~T6/63/Martyr_statue%2C_Battle_of_Asal_Uttar%2C_Punjab.jpg/1920px-Martyr_statue%2C_Battle_of_Asal_Uttar%2C_Punjab.jpg",1600,1200,"Bhaskea","CC-BY-SA","CC BY-SA 4.0","~CFile:Martyr_statue,_Battle_of_Asal_Uttar,_Punjab.jpg"]]],["taindhar-jadunath-memorial","Naik Jadunath Singh Memorial, Taindhar","Naushera","Rajouri","Jammu & Kashmir",33.15,74.23,null,"Indian Army","A memorial at Taindhar Top in the Naushera sector, at the picquet where Naik Jadunath Singh of 1 Rajput fell on 6 February 1948.","It marks one of the defining small-unit actions of the 1947–48 war.",[["Naik Jadunath Singh Memorial, Taindhar","~T2/28/Jadunath_Memorial_at_Taindhar_Top_near_Naushera_J%26K.jpg/1920px-Jadunath_Memorial_at_Taindhar_Top_near_Naushera_J%26K.jpg",1600,2133,"Ashik2k9","CC-BY-SA","CC BY-SA 3.0","~CFile:Jadunath_Memorial_at_Taindhar_Top_near_Naushera_J%26K.jpg"]]]]}$j$::jsonb;
  r jsonb; e jsonb; mid uuid; rid uuid; first_mid uuid;
begin
  for r in select * from jsonb_array_elements(d->'w') loop
    insert into public.wars (slug,name,type,start_date,end_date,period_label,theatre,summary,description,key_events,sources,verification)
    values (r->>0, r->>1, (r->>2)::public.conflict_type, (r->>3)::date, (r->>4)::date, r->>5, r->>6, r->>7, r->>8,
      (select coalesce(jsonb_agg(jsonb_build_object('date',x->>0,'label',x->>1,'title',x->>2,'description',x->>3)),'[]'::jsonb) from jsonb_array_elements(r->9) x),
      public._seed_sources(r->>10), 'verified')
    returning id into rid;
    if jsonb_typeof(r->11) = 'array' then
      mid := public._seed_media(r->11, null, null, rid);
      update public.wars set hero_media_id = mid where id = rid;
    end if;
  end loop;

  for r in select * from jsonb_array_elements(d->'m') loop
    insert into public.memorials (slug,name,city,district,state,latitude,longitude,coords_approximate,inaugurated_year,managed_by,description,significance,sources,verification)
    values (r->>0, r->>1, r->>2, r->>3, r->>4, (r->>5)::float8, (r->>6)::float8, true, (r->>7)::int, r->>8, r->>9, r->>10,
      jsonb_build_array(jsonb_build_object('field','location','title',r->>1,'publisher',r->>8,'url',
        case when r->>0 = 'national-war-memorial' then 'https://nationalwarmemorial.gov.in/' when r->>8 like 'Indian Navy%' then 'https://indiannavy.nic.in/' else 'https://indianarmy.nic.in/' end,
        'tier','primary','accessed','2026-10-22')),
      'verified')
    returning id into rid;
    first_mid := null;
    for e in select * from jsonb_array_elements(r->11) loop
      mid := public._seed_media(e, null, rid, null);
      if first_mid is null then first_mid := mid; end if;
    end loop;
    update public.media set memorial_id = rid where id = first_mid and memorial_id is null;
    update public.memorials set hero_media_id = first_mid where id = rid;
  end loop;

  perform public._seed_people($p$[["somnath-sharma","Somnath Sharma","Major",null,"Army","4th Battalion, The Kumaon Regiment","4 KUMAON","1923-01-31","fell-in-action","1947-11-03","Dadh","Kangra","Himachal Pradesh","first-kashmir-war-1947",null,"Badgam, near Srinagar airfield","Major Somnath Sharma was the first recipient of the Param Vir Chakra. Commissioned into the 19th Hyderabad Regiment (later the Kumaon Regiment) in 1942, he had served in the Arakan campaign in Burma. In October 1947 his left hand was in plaster after a hockey injury, yet he insisted on accompanying his company when 4 Kumaon was flown into Srinagar.\n\nOn 3 November 1947 his company, on patrol near Badgam, was attacked by a lashkar of around 700 raiders. Heavily outnumbered and under fire from three sides, he moved openly between his posts, laid out cloth panels to guide supporting aircraft, and helped fill magazines himself. His last message to brigade headquarters said that he would not withdraw an inch and would fight to the last man and the last round. He was killed by a mortar shell moments later. The six-hour stand bought the time needed for reinforcements to reach the airfield, without which the Valley could not have been held.","GNA","Param Vir Chakra",1950,true,"For defending the Badgam position against an enemy force several times his company's strength, personally moving between sections under heavy fire, and holding ground until he was killed, denying the enemy the approach to Srinagar airfield.",null,["national-war-memorial"],["Bust of Major Somnath Sharma, Param Yodha Sthal, National War Memorial","~T9/94/Major_Somnath_Sharma_statue_at_Param_Yodha_Sthal_Delhi.jpg/1920px-Major_Somnath_Sharma_statue_at_Param_Yodha_Sthal_Delhi.jpg",1600,1600,"Krishna Chaitanya Velaga","CC-BY-SA","CC BY-SA 4.0","~CFile:Major_Somnath_Sharma_statue_at_Param_Yodha_Sthal_Delhi.jpg"]],["jadunath-singh","Jadunath Singh","Naik",null,"Army","1st Battalion, The Rajput Regiment","1 RAJPUT","1916-11-21","fell-in-action","1948-02-06","Khajuri","Shahjahanpur","Uttar Pradesh","first-kashmir-war-1947",null,"Taindhar, Naushera sector","Naik Jadunath Singh enlisted in the Rajput Regiment in 1941 and served in Burma during the Second World War. On 6 February 1948, his section held a picquet on Taindhar ridge, north of Naushera, when a large enemy force attacked in waves.\n\nWith most of his small section wounded, he reorganised them and repelled the first two assaults. When the third came, he took up a Sten gun and charged the attackers alone. He was killed by two bullets to the head and chest, but the attack faltered and the post held until reinforcements arrived. Naushera's defence that day became a turning point of the war in the Jammu sector.","GNA","Param Vir Chakra",1950,true,"For commanding a forward picquet of nine men at Taindhar which repulsed three successive enemy attacks; though wounded, he led the remaining men in a final counter-charge alone and was killed, saving the picquet from capture.",null,["national-war-memorial","taindhar-jadunath-memorial"],["Bust of Naik Jadunath Singh, Param Yodha Sthal, National War Memorial","~Ta/ac/Naik_Jadunath_Singh_statue_at_Param_Yodha_Sthal_Delhi.jpg/1920px-Naik_Jadunath_Singh_statue_at_Param_Yodha_Sthal_Delhi.jpg",1600,1600,"Krishna Chaitanya Velaga","CC-BY-SA","CC BY-SA 4.0","~CFile:Naik_Jadunath_Singh_statue_at_Param_Yodha_Sthal_Delhi.jpg"]],["rama-raghoba-rane","Rama Raghoba Rane","Second Lieutenant",null,"Army","Corps of Engineers (Bombay Sappers), 37 Assault Field Company","37 ASLT FD COY","1918-06-26","survived","1948-04-08","Chendia","Uttara Kannada","Karnataka","first-kashmir-war-1947",null,"Naushera–Rajouri road","Second Lieutenant Rama Raghoba Rane served in the Bombay Sappers. In April 1948, as Indian forces advanced from Naushera towards Rajouri, the road was blocked by mines, felled trees and boulders, all covered by enemy fire.\n\nBetween 8 and 11 April, despite being wounded, Rane and his sappers worked almost without rest to clear the route — on one occasion lying beside a tank and directing it forward by tugging a cord tied to the driver's arm, so that the clearance could continue under fire. The advance reached Rajouri on 11 April. He survived the war, retired as a Major in 1968, and died in 1994.","GNA","Param Vir Chakra",1950,false,"For clearing minefields and roadblocks under continuous enemy fire over several days, at times working from beneath an advancing tank, thereby opening the road to Rajouri for the Indian advance.",null,["national-war-memorial"],["Bust of Second Lieutenant Rama Raghoba Rane, Param Yodha Sthal, National War Memorial","~Tb/b3/Second_Lieutenant_R_R_Rane_statue_at_Param_Yodha_Sthal_Delhi.jpg/1920px-Second_Lieutenant_R_R_Rane_statue_at_Param_Yodha_Sthal_Delhi.jpg",1600,1600,"Krishna Chaitanya Velaga","CC-BY-SA","CC BY-SA 4.0","~CFile:Second_Lieutenant_R_R_Rane_statue_at_Param_Yodha_Sthal_Delhi.jpg"]],["piru-singh","Piru Singh","Company Havildar Major",null,"Army","6th Battalion, The Rajputana Rifles","6 RAJ RIF","1918-05-20","fell-in-action","1948-07-18","Rampura Beri","Jhunjhunu","Rajasthan","first-kashmir-war-1947",null,"Darapari ridge, Tithwal sector","Company Havildar Major Piru Singh joined the Rajputana Rifles in 1936. On 18 July 1948, his company was ordered to capture an enemy-held feature on the Darapari ridge in the Tithwal sector, approached by a narrow ridge swept by machine-gun fire.\n\nAs casualties mounted, he rushed forward with the survivors of the leading section. Wounded by grenade splinters, he bayoneted the crew of one machine-gun post and went on to clear a second. Though blinded in one eye and bleeding heavily, he continued towards a third bunker and threw a grenade into it as he was fatally shot. His example at Tithwal is commemorated by his regiment to this day.","GNA","Param Vir Chakra",null,true,"For leading the assault on a strongly held enemy position near Tithwal after most of his section had fallen, silencing successive machine-gun posts with grenade and bayonet despite grievous wounds, until he was killed.",null,["national-war-memorial"],["Bust of Company Havildar Major Piru Singh, Param Yodha Sthal, National War Memorial","~T3/3a/Piru_Singh_statue_at_Param_Yodha_Sthal_Delhi.jpg/1920px-Piru_Singh_statue_at_Param_Yodha_Sthal_Delhi.jpg",1600,1600,"Krishna Chaitanya Velaga","CC-BY-SA","CC BY-SA 4.0","~CFile:Piru_Singh_statue_at_Param_Yodha_Sthal_Delhi.jpg"]],["karam-singh","Karam Singh","Lance Naik",null,"Army","1st Battalion, The Sikh Regiment","1 SIKH","1915-09-15","survived","1948-10-13","Sehna","Barnala","Punjab","first-kashmir-war-1947",null,"Richhmar Gali, Tithwal sector","Lance Naik Karam Singh had already won the Military Medal in Burma in 1944. On 13 October 1948, the enemy launched a major offensive to recapture Richhmar Gali, south of Tithwal, preceded by heavy shelling.\n\nCommanding a forward section, he held the position through eight successive attacks. Wounded twice, he went from bunker to bunker carrying ammunition and evacuating the injured, and when the enemy reached his trenches he led his men out with bayonets. The post did not fall. Karam Singh was one of the soldiers selected to hoist the national flag at the first Republic Day celebrations. He retired as an Honorary Captain and died in 1993.","GNA","Param Vir Chakra",1950,false,"For holding a forward post at Richhmar Gali against eight determined enemy attacks during a single day, moving between bunkers while wounded to encourage his men and leading counter-attacks with the bayonet.",null,["national-war-memorial"],["Bust of Lance Naik Karam Singh, Param Yodha Sthal, National War Memorial","~Ta/a9/Lance_Naik_Karam_Singh_statue_at_Param_Yodha_Sthal_Delhi.jpg/1920px-Lance_Naik_Karam_Singh_statue_at_Param_Yodha_Sthal_Delhi.jpg",1600,1704,"Krishna Chaitanya Velaga","CC-BY-SA","CC BY-SA 4.0","~CFile:Lance_Naik_Karam_Singh_statue_at_Param_Yodha_Sthal_Delhi.jpg"]],["gurbachan-singh-salaria","Gurbachan Singh Salaria","Captain",null,"Army","3rd Battalion, 1 Gorkha Rifles","3/1 GR","1935-11-29","fell-in-action","1961-12-05","Janwal","Shakargarh","Punjab","onuc-congo-1961","ONUC","Elisabethville, Katanga, Congo","Captain Gurbachan Singh Salaria is the only United Nations peacekeeper to have received the Param Vir Chakra. An alumnus of the King George's Royal Military College and the National Defence Academy, he was commissioned into 3/1 Gorkha Rifles in 1957.\n\nOn 5 December 1961, at Elisabethville, his platoon of about sixteen men was tasked with clearing a roadblock held by some ninety gendarmes and mercenaries supported by armoured cars. Leading the charge with kukris, grenades and rocket launchers, his men killed around forty of the enemy and destroyed two armoured cars. Hit twice in the neck by automatic fire, he continued to fight until he collapsed. He was 26.","GNAU","Param Vir Chakra",1962,true,"For leading a small force of Gorkhas in a charge against a roadblock held by a much larger force of Katangese gendarmes and mercenaries with armoured cars, killing many of the enemy at close quarters and continuing to fight after being mortally wounded.",null,["national-war-memorial"],["Bust of Captain Gurbachan Singh Salaria, Param Yodha Sthal, National War Memorial","~T6/63/Captain_Salaria_statue_at_Param_Yodha_Sthal_Delhi.jpg/1920px-Captain_Salaria_statue_at_Param_Yodha_Sthal_Delhi.jpg",1600,1600,"Krishna Chaitanya Velaga","CC-BY-SA","CC BY-SA 4.0","~CFile:Captain_Salaria_statue_at_Param_Yodha_Sthal_Delhi.jpg"]],["dhan-singh-thapa","Dhan Singh Thapa","Major",null,"Army","1st Battalion, 8 Gorkha Rifles","1/8 GR","1928-04-10","survived","1962-10-20","Shimla","Shimla","Himachal Pradesh","sino-indian-war-1962",null,"Srijap-1 post, north of Pangong Tso, Ladakh","Major Dhan Singh Thapa commanded a platoon-strength post at Srijap-1 on the northern shore of Pangong Tso. On 20 October 1962, the post came under heavy artillery and mortar fire and was attacked by a force many times its size.\n\nThe Gorkhas repulsed two assaults, inflicting heavy casualties. In the third attack, supported by tanks, the post was overrun; Thapa fought hand-to-hand until he was overpowered and captured. Believed killed, he was at first announced as a posthumous recipient. He returned from captivity after the war, retired as a Lieutenant Colonel, and died in 2005.","GNA","Param Vir Chakra",1962,false,"For commanding the Srijap-1 post against overwhelming Chinese attacks supported by artillery and tanks, repelling assaults until the post was overrun, and continuing to fight hand-to-hand before being taken prisoner.",null,["national-war-memorial"],["Bust of Major Dhan Singh Thapa, Param Yodha Sthal, National War Memorial","~T4/43/Major_Dhan_Singh_Thapa_statue_at_Param_Yodha_Sthal_Delhi.jpg/1920px-Major_Dhan_Singh_Thapa_statue_at_Param_Yodha_Sthal_Delhi.jpg",1600,1600,"Krishna Chaitanya Velaga","CC-BY-SA","CC BY-SA 4.0","~CFile:Major_Dhan_Singh_Thapa_statue_at_Param_Yodha_Sthal_Delhi.jpg"]],["joginder-singh","Joginder Singh","Subedar",null,"Army","1st Battalion, The Sikh Regiment","1 SIKH","1921-09-26","fell-in-action","1962-10-23","Mahla Kalan","Moga","Punjab","sino-indian-war-1962",null,"IB Ridge, near Bum La, Tawang","Subedar Joginder Singh enlisted in 1 Sikh in 1936 and served in the Second World War and in Jammu & Kashmir in 1947–48. In October 1962 his platoon held a position on IB Ridge, covering the approach from Bum La to Tawang.\n\nOn 23 October, the Chinese attacked in strength. His platoon beat back the first two waves; badly wounded in the thigh, he refused evacuation and took over a light machine-gun himself. When the third wave came and the platoon had almost no ammunition left, he and the survivors fixed bayonets and charged. He was captured, severely wounded, and died of his wounds in captivity.","GNA","Param Vir Chakra",1962,true,"For commanding his platoon on IB Ridge against three waves of Chinese attacks, continuing to man a light machine-gun after being wounded, and leading a final bayonet charge when ammunition ran out.",null,["national-war-memorial","tawang-war-memorial"],["Bust of Subedar Joginder Singh, Param Yodha Sthal, National War Memorial","~Tb/b5/Subedar_Joginder_Singh_statue_at_Param_Yodha_Sthal_Delhi.jpg/1920px-Subedar_Joginder_Singh_statue_at_Param_Yodha_Sthal_Delhi.jpg",1600,1600,"Krishna Chaitanya Velaga","CC-BY-SA","CC BY-SA 4.0","~CFile:Subedar_Joginder_Singh_statue_at_Param_Yodha_Sthal_Delhi.jpg"]],["jaswant-singh-rawat","Jaswant Singh Rawat","Rifleman",null,"Army","4th Battalion, The Garhwal Rifles","4 GARH RIF","1941-08-19","fell-in-action","1962-11-17","Baryun","Pauri Garhwal","Uttarakhand","sino-indian-war-1962",null,"Nuranang, near Sela Pass","Rifleman Jaswant Singh Rawat served with 4 Garhwal Rifles, which fought a determined defensive battle at Nuranang on 17 November 1962. When an enemy medium machine-gun was causing heavy casualties, he and two comrades crept forward under covering fire, lobbed grenades and captured the weapon.\n\nHe was killed during the action. The battalion was awarded the battle honour Nuranang. Jaswant Garh, the memorial built where he fell, keeps his quarters maintained by serving soldiers, and local accounts of his last stand have grown into one of the Army's best-known legends.","GNA","Maha Vir Chakra",null,true,"For volunteering with two comrades to close in on an enemy medium machine-gun that was inflicting heavy casualties on his company, silencing it, and continuing to fight until he was killed.",null,["national-war-memorial","jaswant-garh-war-memorial","tawang-war-memorial"],null],["shaitan-singh","Shaitan Singh","Major",null,"Army","13th Battalion, The Kumaon Regiment","13 KUMAON","1924-12-01","fell-in-action","1962-11-18","Banasar","Jodhpur","Rajasthan","sino-indian-war-1962",null,"Rezang La, Chushul","Major Shaitan Singh commanded C Company of 13 Kumaon, largely Ahir soldiers from Haryana, holding Rezang La pass at about 5,000 metres on the approaches to Chushul. The position was cut off by a ridge from Indian artillery support.\n\nIn the early hours of 18 November 1962, Chinese troops attacked in successive waves. The company fought until almost every man had fallen — of about 120 soldiers, 114 were killed. Shaitan Singh, wounded in the arm and abdomen, ordered the two men carrying him to leave him and rejoin the fight. His body was found three months later, still at his post. Rezang La is commemorated as one of the finest last stands in military history.","GNA","Param Vir Chakra",1963,true,"For commanding C Company at Rezang La against repeated attacks by a vastly superior force with artillery support, moving from post to post under heavy fire to encourage his men, and refusing to be evacuated after being severely wounded.",null,["national-war-memorial","rezang-la-war-memorial"],["Bust of Major Shaitan Singh, Param Yodha Sthal, National War Memorial","~Tc/cb/Major_Shaitan_Singh_statue_at_Param_Yodha_Sthal_Delhi.jpg/1920px-Major_Shaitan_Singh_statue_at_Param_Yodha_Sthal_Delhi.jpg",1600,1600,"Krishna Chaitanya Velaga","CC-BY-SA","CC BY-SA 4.0","~CFile:Major_Shaitan_Singh_statue_at_Param_Yodha_Sthal_Delhi.jpg"]],["abdul-hamid","Abdul Hamid","Company Quarter Master Havildar",null,"Army","4th Battalion, The Grenadiers","4 GRENADIERS","1933-07-01","fell-in-action","1965-09-10","Dhamupur","Ghazipur","Uttar Pradesh","indo-pak-war-1965",null,"Asal Uttar, Khem Karan sector","Company Quarter Master Havildar Abdul Hamid commanded a recoilless gun detachment of 4 Grenadiers in the Khem Karan sector. When Pakistani armour attacked near Cheema village on 10 September 1965, he manoeuvred his jeep-mounted gun into flanking positions among the sugarcane fields.\n\nOver the course of the battle he is credited with destroying several Patton tanks. While engaging another tank, his jeep was hit and he was killed. His actions were part of the defeat of Pakistan's armoured thrust at Asal Uttar, one of the largest tank battles since the Second World War.","GNA","Param Vir Chakra",1965,true,"For engaging and destroying enemy Patton tanks with a jeep-mounted recoilless gun at Asal Uttar, repeatedly changing position under heavy fire, until he was killed while engaging yet another tank.",null,["national-war-memorial","asal-uttar-war-memorial"],["Bust of Company Quarter Master Havildar Abdul Hamid, Param Yodha Sthal, National War Memorial","~T4/42/CQHM_Abdul_Hamid_statue_at_Param_Yodha_Sthal_Delhi.jpg/1920px-CQHM_Abdul_Hamid_statue_at_Param_Yodha_Sthal_Delhi.jpg",1600,1600,"Krishna Chaitanya Velaga","CC-BY-SA","CC BY-SA 4.0","~CFile:CQHM_Abdul_Hamid_statue_at_Param_Yodha_Sthal_Delhi.jpg"]],["ardeshir-burzorji-tarapore","Ardeshir Burzorji Tarapore","Lieutenant Colonel",null,"Army","The Poona Horse (17 Horse)","17 HORSE","1923-08-18","fell-in-action","1965-09-16","Bombay","Mumbai","Maharashtra","indo-pak-war-1965",null,"Phillora–Chawinda, Sialkot sector","Lieutenant Colonel A.B. Tarapore commanded the Poona Horse during the 1965 war. Between 11 and 16 September his regiment spearheaded the advance in the Sialkot sector, fighting at Phillora, Wazirwali, Jassoran and Butur Dograndi.\n\nWounded on 11 September, he refused to be evacuated and continued to lead from the front. On 16 September, during the battle for Chawinda, his tank was hit and he was killed. The regiment is credited with destroying around sixty Pakistani tanks during these actions.","GNA","Param Vir Chakra",1965,true,"For leading his regiment through six days of continuous armoured battle in the Sialkot sector, refusing evacuation when wounded, and destroying some sixty enemy tanks before he was killed when his tank was hit.",null,["national-war-memorial"],["Bust of Lieutenant Colonel Ardeshir Burzorji Tarapore, Param Yodha Sthal, National War Memorial","~T5/50/Lt_Col_A_B_Tarapore_statue_at_Param_Yodha_Sthal_Delhi.jpg/1920px-Lt_Col_A_B_Tarapore_statue_at_Param_Yodha_Sthal_Delhi.jpg",1600,1600,"Krishna Chaitanya Velaga","CC-BY-SA","CC BY-SA 4.0","~CFile:Lt_Col_A_B_Tarapore_statue_at_Param_Yodha_Sthal_Delhi.jpg"]],["ajjamada-boppayya-devayya","Ajjamada Boppayya Devayya","Squadron Leader",null,"Air Force","No. 1 Squadron, Indian Air Force","No. 1 SQN","1932-12-24","fell-in-action","1965-09-07","Kodagu","Kodagu","Karnataka","indo-pak-war-1965",null,"Over Sargodha airbase","Squadron Leader A.B. Devayya, from Kodagu in Karnataka, flew a Dassault Mystère IVA with No. 1 Squadron during the strike on Sargodha airbase on 7 September 1965. As the formation withdrew, an F-104 Starfighter attacked.\n\nDevayya turned to engage it and, according to later accounts, damaged or downed the faster aircraft before he was himself shot down. He was listed as missing for years. His Maha Vir Chakra was awarded posthumously in 1988, more than two decades after the action, once details emerged.","GNI","Maha Vir Chakra",1988,true,"For pressing home an attack on Sargodha airbase in a Mystère and then turning to engage an attacking enemy Starfighter, accounting for it before his own aircraft was lost.",null,["national-war-memorial"],null]]$p$::jsonb);
end
